def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    mod = 1_000_000_007
    transitions = [{}]
    failure = [0]
    forbidden = [False]

    for word in banned:
        state = 0
        for char in word:
            if char not in transitions[state]:
                transitions[state][char] = len(transitions)
                transitions.append({})
                failure.append(0)
                forbidden.append(False)
            state = transitions[state][char]
        forbidden[state] = True

    queue = deque()
    for char in alphabet:
        if char in transitions[0]:
            queue.append(transitions[0][char])
        else:
            transitions[0][char] = 0

    while queue:
        state = queue.popleft()
        forbidden[state] |= forbidden[failure[state]]
        for char in alphabet:
            if char in transitions[state]:
                child = transitions[state][char]
                failure[child] = transitions[failure[state]][char]
                queue.append(child)
            else:
                transitions[state][char] = transitions[failure[state]][char]

    safe_states = [state for state in range(len(transitions)) if not forbidden[state]]
    indices = {state: i for i, state in enumerate(safe_states)}
    size = len(safe_states)

    matrix = [[0] * size for _ in range(size)]
    for i, state in enumerate(safe_states):
        for char in alphabet:
            next_state = transitions[state][char]
            if not forbidden[next_state]:
                matrix[i][indices[next_state]] += 1

    counts = [0] * size
    counts[indices[0]] = 1

    while n:
        if n & 1:
            next_counts = [0] * size
            for i, count in enumerate(counts):
                if count:
                    for j, value in enumerate(matrix[i]):
                        if value:
                            next_counts[j] = (next_counts[j] + count * value) % mod
            counts = next_counts

        n >>= 1
        if n:
            squared = [[0] * size for _ in range(size)]
            for i in range(size):
                for k, left in enumerate(matrix[i]):
                    if left:
                        for j, right in enumerate(matrix[k]):
                            if right:
                                squared[i][j] = (squared[i][j] + left * right) % mod
            matrix = squared

    return sum(counts) % mod
